      'login-providers',
      'tenants-terms-of-use',
      'users',
      'user-federated-identities',
      'template',
      'smtp-outbound-config',
      'alerts',
      'alert-rules',
      'dashboards',
      'embeds',
      'issues',
      'probes',
      'slos',
      'sources',
      'snippet',
      'snippet-asset',
      'snippet-versions',
      'template-template',
      'template-asset',
      'template-variable',
      'template-versions',
      'theme',
      'theme-asset',
      'theme-versions',
